# Python 3.10+ standard library only.

from __future__ import annotations


class ConfigError(Exception):
    """Raised when a configuration value cannot be coerced or is missing a default.

    Attributes:
        key: the configuration key that caused the error.
        expected: the type or value that was expected.
        actual: the value that was found (if any).
    """

    def __init__(self, key: str, expected: str, actual: str | None = None):
        self.key = key
        self.expected = expected
        self.actual = actual
        msg = f"{key}: expected {expected}"
        if actual is not None:
            msg += f", got {actual!r}"
        super().__init__(msg)


def _coerce(value: str, expected: type) -> any:
    """Coerce a string to the given type, raising ConfigError on failure.

    Supported types: int, float, bool, str.
    """
    if expected is str:
        return value
    if expected is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(value, "bool")
    if expected is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(value, "int")
    if expected is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(value, "float")
    raise ConfigError(value, repr(expected))


